source:
source note sys.dataset(fields: [title, summary, as_of, status, metric1_label, metric1_value, metric2_label, metric2_value, pick1_title, pick1_body, pick2_title, pick2_body])

state mode { shape: enum[brief, code, details], initial: .brief }
event show_code { mode: set(.code) }
event show_details { mode: set(.details) }
event back { mode: set(.brief) }

copy app { class: vocabulary, en: "Mail" }
copy sim { class: vocabulary, en: "Simulation" }
copy l_code { class: vocabulary, en: "Show pickup code" }
copy l_details { class: vocabulary, en: "Pickup details" }
copy l_back { class: vocabulary, en: "Back" }
copy gist { class: model-copy, en: "Bring code 4821 and photo ID to the pickup desk by Mon, Oct 5, 9:00 PM PDT." }

view root Surface(pad: .tight) {
  Col(gap: 8) {
    Row(gap: 8, align: .center) {
      Icon(name: .mail, size: .row)
      TextCaption(text: copy.app, width: .fill)
      TextCaption(value: note.as_of)
    }
    Row(gap: 6, align: .center) {
      TextCaption(text: copy.sim)
      TextCaption(value: note.status)
    }
    when mode == .brief {
      TextTitle(text: note.title, width: .fill)
      TextBody(text: note.summary, width: .fill)
      TextCaption(text: copy.gist, width: .fill)
      Row(gap: 8) {
        Chip(text: copy.l_code, on_tap: show_code, tone: .primary)
        Chip(text: copy.l_details, on_tap: show_details, tone: .primary)
      }
    }
    when mode == .code {
      TextCaption(text: note.metric1_label, width: .fill)
      TextTitle(text: note.metric1_value, width: .fill)
      TextCaption(text: copy.gist, width: .fill)
      Chip(text: copy.l_back, on_tap: back, tone: .normal)
    }
    when mode == .details {
      TextTitle(text: note.metric2_value, width: .fill)
      TextCaption(text: note.metric2_label, width: .fill)
      TextCaption(text: note.pick1_title, width: .fill)
      TextBody(text: note.pick1_body, width: .fill)
      TextCaption(text: note.pick2_title, width: .fill)
      TextBody(text: note.pick2_body, width: .fill)
      Chip(text: copy.l_back, on_tap: back, tone: .normal)
    }
  }
}
